n8n_code_node_examples.discovery_response:
// Code node for MCP Discovery workflow
const tools = [
  {
    name: 'search_database',
    description: 'Search the database for records',
    endpoint: 'http://localhost:5678/webhook/search-database',
    input_schema: {
      type: 'object',
      properties: {
        query: { type: 'string', description: 'Search query' },
        limit: { type: 'number', description: 'Max results', default: 10 }
      },
      required: ['query']
    }
  },
  // Add more tools here
];

return [{ json: { tools } }];

n8n_code_node_examples.tool_input_validation:
// Code node to validate tool inputs
const input = $input.first().json;

// Validate required fields
if (!input.query) {
  throw new Error('Missing required field: query');
}

const limit = input.limit || 10;

return [{
  json: {
    query: input.query,
    limit: Math.min(limit, 100) // Cap at 100
  }
}];

n8n_code_node_examples.format_mcp_response:
// Code node to format response in MCP format
const results = $input.first().json;

return [{
  json: {
    success: true,
    data: results,
    metadata: {
      timestamp: new Date().toISOString(),
      tool_name: 'search_database'
    }
  }
}];
